input.command:
cat > /tmp/probe.exp <<'EOF'
#!/usr/bin/expect -f
set timeout 60
log_user 1
spawn qemu-system-x86_64 -m 1024 -smp 2 -cdrom /app/alpine.iso -boot d -nographic -netdev user,id=n1,hostfwd=tcp::2222-:22 -device virtio-net-pci,netdev=n1 -no-reboot
expect {
  "boot:" { send "\t"; sleep 3; send "\r"; exp_continue }
  timeout { puts "\nPROBE_TIMEOUT"; exit 1 }
  eof { puts "\nPROBE_EOF"; exit 1 }
}
EOF
chmod +x /tmp/probe.exp
timeout 90 /tmp/probe.exp 2>&1 | tail -60

cat > /tmp/bootprobe.exp <<'EOF'
#!/usr/bin/expect -f
set timeout 150
log_user 1
log_file -a /tmp/bootprobe.log
spawn qemu-system-x86_64 -m 1024 -smp 2 -cdrom /app/alpine.iso -boot d -nographic -netdev user,id=n1,hostfwd=tcp::2222-:22 -device virtio-net-pci,netdev=n1 -no-reboot
expect {
  "boot:" { send "lts console=ttyS0,115200\r"; exp_continue }
  -re "(login|Welcome to Alpine)" { puts "\nGOT_LOGIN"; sleep 2; exit 0 }
  timeout { puts "\nNO_LOGIN"; exit 1 }
  eof { puts "\nEOF"; exit 1 }
}
EOF
chmod +x /tmp/bootprobe.exp
timeout 170 /tmp/bootprobe.exp 2>&1 | tail -40

cat > /tmp/setup.exp <<'EOF'
#!/usr/bin/expect -f
set timeout 300
log_user 1
log_file -a /tmp/setup.log
spawn qemu-system-x86_64 -m 1024 -smp 2 -cdrom /app/alpine.iso -boot d -nographic -netdev user,id=n1,hostfwd=tcp::2222-:22 -device virtio-net-pci,netdev=n1 -no-reboot
expect "boot:"
set cmd "lts console=ttyS0,115200"
foreach c [split $cmd ""] { send -- $c; sleep 0.05 }
send "\r"
expect {
  -re "(login:)" { }
  timeout { puts "\nNO_LOGIN_PROMPT"; exit 1 }
  eof { puts "\nEOF_BEFORE_LOGIN"; exit 1 }
}
send "root\r"
expect {
  -re "# $" { }
  timeout { puts "\nNO_SHELL"; exit 1 }
}
send "ip link set eth0 up\r"
sleep 1
send "udhcpc -i eth0\r"
sleep 5
send "apk update\r"
expect {
  -re "# $" { }
  timeout { puts "\nAPK_UPDATE_TIMEOUT"; }
}
send "apk add openssh\r"
expect {
  -re "# $" { }
  timeout { puts "\nAPK_ADD_TIMEOUT"; }
}
send "ssh-keygen -A\r"
sleep 2
send "echo 'root:password123' | chpasswd\r"
sleep 2
send "echo 'PermitRootLogin yes' >> /etc/ssh/sshd_config\r"
send "echo 'PasswordAuthentication yes' >> /etc/ssh/sshd_config\r"
send "/usr/sbin/sshd -o PermitRootLogin=yes -o PasswordAuthentication=yes\r"
sleep 2
send "echo SETUP_DONE\r"
expect "SETUP_DONE"
puts "\nSETUP_COMPLETE"
while {1} { sleep 3600 }
EOF
chmod +x /tmp/setup.exp
setsid nohup /tmp/setup.exp > /tmp/setup.out 2>&1 < /dev/null &
echo started; sleep 20; tail -c 800 /tmp/setup.out | cat -v
